// Selection quote (conversationQuotes) — the structured payload of the
// official `sendText` schema (app.asar @316542246, runtime @1296577). The
// declared shapes and the four hard limits mirror the runtime validator
// (@749223); the `# userselect` prompt fence is generated by the desktop
// runtime, never by this client.
//
// Widget-free by design (protocol layer): the model, the wire mapping and
// the limit verdict are pure so both the composer and the unit tests share
// one source of truth.

/// One quoted selection, mapped 1:1 onto the official conversationQuotes
/// entry. `text` is required; `comment` is the user's annotation; the rest
/// are optional provenance fields the official schema accepts (path is for
/// file selections, sender/message fields for conversation rows).
class ConversationQuote {
  final String text;
  final String? comment;
  final String? path;
  final String? senderName;
  final String? senderId;
  final String? messageId;
  final int? sentAt;
  final String? agent;

  const ConversationQuote({
    required this.text,
    this.comment,
    this.path,
    this.senderName,
    this.senderId,
    this.messageId,
    this.sentAt,
    this.agent,
  });

  /// Wire object: empty optional members are omitted (the runtime schema
  /// marks them optional; sending empty strings would only add noise).
  Map<String, dynamic> toWire() => {
    'text': text,
    if (comment != null && comment!.isNotEmpty) 'comment': comment,
    if (path != null && path!.isNotEmpty) 'path': path,
    if (senderName != null && senderName!.isNotEmpty)
      'senderName': senderName,
    if (senderId != null && senderId!.isNotEmpty) 'senderId': senderId,
    if (messageId != null && messageId!.isNotEmpty) 'messageId': messageId,
    if (sentAt != null) 'sentAt': sentAt,
    if (agent != null && agent!.isNotEmpty) 'agent': agent,
  };
}

/// Runtime hard limits (runtime @749223). Values are character counts on
/// the Dart string, matching the desktop's own length checks.
abstract final class ConversationQuoteLimits {
  static const maxCount = 8;
  static const maxTextLength = 8000;
  static const maxTotalTextLength = 16000;
  static const maxCommentLength = 2000;
  static const maxAgentLength = 200;
}

/// The i18n key of the FIRST violated limit, or null when [quotes] fits the
/// runtime schema. Messages reuse the official `chat.selections.limit.*`
/// family; callers toast the translated key and refuse the send.
String? conversationQuoteLimitErrorKey(List<ConversationQuote> quotes) {
  if (quotes.length > ConversationQuoteLimits.maxCount) {
    return 'chat.selections.limit.count';
  }
  var total = 0;
  for (final quote in quotes) {
    if (quote.text.length > ConversationQuoteLimits.maxTextLength) {
      return 'chat.selections.limit.single';
    }
    total += quote.text.length;
    final comment = quote.comment;
    if (comment != null &&
        comment.length > ConversationQuoteLimits.maxCommentLength) {
      return 'chat.selections.limit.comment';
    }
    final agent = quote.agent;
    if (agent != null &&
        agent.length > ConversationQuoteLimits.maxAgentLength) {
      return 'chat.selections.limit.agent';
    }
  }
  if (total > ConversationQuoteLimits.maxTotalTextLength) {
    return 'chat.selections.limit.total';
  }
  return null;
}

/// Reads the capability probe's answer. The official method
/// (`supportsConversationQuoteComment`, app.asar @319128691) answers a plain
/// boolean; map-shaped answers are tolerated. Anything else is UNKNOWN —
/// never a negative verdict (unknown-method / transient failures must not
/// hide the entry, PRD R4).
bool? parseQuoteSupportVerdict(dynamic res) {
  if (res is bool) return res;
  if (res is Map) {
    for (final key in const ['supported', 'enabled', 'available']) {
      final value = res[key];
      if (value is bool) return value;
    }
  }
  return null;
}

/// Arguments of the `supportsConversationQuoteComment` probe, derived from
/// the active workspace. Live capture (2026-11-14, desktop 3.18.2) pinned the
/// wire: an EMPTY argument list makes the desktop throw
/// `Cannot read properties of undefined (reading 'workspaceIdentity')`, while
/// a one-element `[{workspacePath, workspaceIdentity?}]` list answers the
/// real boolean (true on 3.18.2). Null when no workspace path is known —
/// probing without one is guaranteed noise.
List<Object?>? conversationQuoteProbeArgs(Map<String, dynamic>? workspace) {
  final path = workspace?['workspacePath'];
  if (path is! String || path.isEmpty) return null;
  return [
    {
      'workspacePath': path,
      if (workspace!['workspaceIdentity'] != null)
        'workspaceIdentity': workspace['workspaceIdentity'],
    },
  ];
}

/// Entry gate (PRD R4): the version gate is the primary signal; the
/// capability probe only contributes NEGATIVE evidence — an explicit
/// `false` hides the entry, while unknown (null) and transient failures
/// keep it visible.
bool selectionQuoteEntryAllowed({
  required bool versionOk,
  required bool? probeVerdict,
}) => versionOk && probeVerdict != false;
